    [5542]={name="Pearl-clasped Cloak",quality=2,ilvl=19,reqLevel=14,sourceType="profession",instructions="Crafted with Tailoring (requires skill 1).",profession="Tailoring"},
    [5581]={name="Smooth Walking Staff",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'The Stolen Journal' - pick it over the other choices. In Coldridge Valley.",zone="Coldridge Valley",questName="The Stolen Journal",lore="My journal! They took it away to the cave. The one that had it... It was a big brute with some odd markings on his skin and face. I didn't get a much better look than that."},
    [5591]={name="Rain-spotted Cape",quality=1,ilvl=11,sourceType="quest_reward",instructions="Reward from the quest 'The Enchanted Glade' - pick it over the other choices. In Teldrassil.",zone="Teldrassil",questName="The Enchanted Glade",lore="I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade."},
    [5611]={name="Tear of Grief",quality=2,ilvl=16,sourceType="quest_reward",instructions="Reward from the quest 'For Love Eternal'. In Darkshore.",zone="Darkshore",questName="For Love Eternal",lore="In the aftermath of the battles at the Well of Eternity, I heard that Ameth'Aran had been destroyed, its people dead, including my love, Anaya."},
    [5617]={name="Vagabond Leggings",quality=2,ilvl=13,sourceType="quest_reward",instructions="Reward from the quest 'Bashal'Aran' - pick it over the other choices. In Darkshore.",zone="Darkshore",questName="Bashal'Aran",lore="It was the craft of one of the most powerful of the Highborne that created the seal that formed my prison. In Ameth'Aran, the ruins to the south that are twin to these, persists even today an ancient flame, blue in color."},
    [5754]={name="Wolfpack Medallion",quality=2,ilvl=31,reqLevel=26,sourceType="world_drop",instructions="Drops from Terrowulf Packlord (rare spawn) in Kalimdor.",zone="Kalimdor",npc="Terrowulf Packlord"},
    [5756]={name="Sliverblade",quality=3,ilvl=37,reqLevel=32,sourceType="world_drop",instructions="World drop - drops from 38 creature types around level 29-40. Also found on the auction house.",proc="Chance on hit: Blasts a target for 45 Frost damage."},
    [5777]={name="Brave's Axe",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Rite of Strength' - pick it over the other choices. In Red Cloud Mesa.",zone="Red Cloud Mesa",questName="Rite of Strength",lore="The Rites of the Earthmother are the steps a young tauren needs to take to gain respect in Thunder Bluff. First you must pass the Rite of Strength."},
