    [6719]={name="Windborne Belt",quality=2,ilvl=30,sourceType="quest_reward",instructions="Reward from the quest 'Highperch Venom'. In Dustwallow Marsh.",zone="Dustwallow Marsh",questName="Highperch Venom",lore="As you may know, wyverns are often tamed by orcs for use as mounts. But what is less known is that the venom of a wyvern, in some circles, is more valuable than the beast itself."},
    [6723]={name="Medal of Courage",quality=3,ilvl=45,sourceType="quest_reward",instructions="Reward from the quest 'Saving Yenniku' - pick it over the other choices. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="Saving Yenniku",lore="I have reshaped the Mind's Eye into a Soul Gem. Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul."},
    [6744]={name="Gloves of Kapelan",quality=2,ilvl=33,sourceType="quest_reward",instructions="Reward from the quest 'Alliance Relations' - pick it over the other choices. In Orgrimmar.",zone="Orgrimmar",questName="Alliance Relations",lore="The fight goes well. Perhaps the Warchief will allow us to return to our homes before the seasons change if we continue to make such great strides in our battle against the demons and their underlings."},
    [6750]={name="Snake Hoop",quality=2,ilvl=31,sourceType="quest_reward",instructions="Reward from the quest 'Willix the Importer' - pick it over the other choices. In Razorfen Kraul.",zone="Razorfen Kraul",questName="Willix the Importer",lore="At last, help has arrived! You have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place."},
    [6773]={name="Gelkis Marauder Chain",quality=2,ilvl=42,sourceType="quest_reward",instructions="Reward from the quest 'Khan Hratha' - pick it over the other choices. In Desolace.",zone="Desolace",questName="Khan Hratha",lore="you helped us against the Magram. Now, help us beat the Maraudine! Kill the head of their clan, Khan Hratha! To face him, blow the Maraudine War Horn."},
    [6804]={name="Windstorm Hammer",quality=3,ilvl=34,sourceType="quest_reward",instructions="Reward from the quest 'Final Passage' - pick it over the other choices. In Thousand Needles.",zone="Thousand Needles",questName="Final Passage",lore="You have done well. You have passed my test, and the tests before mine. Return to Dorn in Thousand Needles."},
    [6831]={name="Black Menace",quality=3,ilvl=44,sourceType="quest_reward",instructions="Reward from the quest 'In the Name of the Light' - pick it over the other choices. In Scarlet Monastery.",zone="Scarlet Monastery",questName="In the Name of the Light",lore="I once served the Scarlet Crusade with honor, loyalty and pride. I believed their cause to be a noble one: to rid Azeroth of the undead.",proc="Chance on hit: Sends a shadowy bolt at the enemy causing 30 Shadow damage."},
