    [6902]={name="Bands of Serra'kis",quality=3,ilvl=27,reqLevel=22,sourceType="boss_drop",instructions="Drops from Old Serra'kis in Blackfathom Deeps.",zone="Blackfathom Deeps",npc="Old Serra'kis",lore="Serra'kis is the great water beast the naga breed in the flooded halls of Blackfathom Deeps, and the reason the lower temple is under water at all."},
