    [15399]={name="Dryweed Belt",quality=2,ilvl=14,sourceType="quest_reward",instructions="Reward from the quest 'Washed Ashore' - pick it over the other choices. In Darkshore.",zone="Darkshore",questName="Washed Ashore",lore="That beached creature is not an isolated incident here in Darkshore. There are more along the coastline and even in the water."},
    [15443]={name="Kris of Orgrimmar",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'Hidden Enemies' - pick it over the other choices. In Orgrimmar.",zone="Orgrimmar",questName="Hidden Enemies",lore="You are one of my lieutenants! Prepare yourself. I will call upon you soon. My time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer."},
    [15449]={name="Ghastly Trousers",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'The Power to Destroy...' - pick it over the other choices. In Ragefire Chasm.",zone="Ragefire Chasm",questName="The Power to Destroy...",lore="Many denizens of the Legion bestow gifts on their followers as you may well know. Some of these gifts the Dark Lady feels would be better off in her hands than in the hands of those with..."},
    [15452]={name="Featherbead Bracers",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'Returning the Lost Satchel' - pick it over the other choices. In Ragefire Chasm.",zone="Ragefire Chasm",questName="Returning the Lost Satchel",lore="You find a satchel under the body of the tauren. It is still gripped tightly in his arms as though he was trying to protect it while being attacked by the troggs."},
    [15466]={name="Clink Shield",quality=2,ilvl=28,sourceType="quest_reward",instructions="Reward from the quest 'Arikara' - pick it over the other choices. In Thousand Needles.",zone="Thousand Needles",questName="Arikara",lore="Take this refined and purified Incendia powder to Thousand Needles and toss it on the sacred fire of life. It is located in the Darkcloud Pinnacle on an isolated needle where they bury their dead."},
    [15468]={name="Windsong Drape",quality=2,ilvl=29,sourceType="quest_reward",instructions="Reward from the quest 'Free at Last' - pick it over the other choices. In Thousand Needles.",zone="Thousand Needles",questName="Free at Last",lore="Arnak thinks we're going to be married... but after I declined his offer he came back that night and kidnapped me. My brother tried to stop him, but Arnak was too strong."},
